VRS_st.name='VRS'; 
VRS_st.lat=81.6;
VRS_st.lon=-16.67;
VRS_st.alt=24;
VRS_st.env='P';
VRS_st.footp='P' %[output:38fe3bf4]
%%

%%VRS_rd=read_betsy_h('C:\github_trend\raw_data\vrs_aeth_2017_2025_gmlfmt',VRS_st.name);
% read from import file


names_rd=fieldnames(VRS_rd);
for i=1:length(names_rd)-3
    VRS_rd.(names_rd{i})(VRS_rd.(names_rd{i})>999)=NaN;
end

names_rd=fieldnames(VRS_rd);
%%
