VRS_rd.Properties.DimensionNames{1}='Time';

VRS_rd.Properties.VariableNames{1}='Ba1_A';
VRS_rd.Properties.VariableNames{2}='Ba2_A';
VRS_rd.Properties.VariableNames{3}='Ba3_A';
VRS_rd.Properties.VariableNames{4}='Ba4_A';
VRS_rd.Properties.VariableNames{5}='Ba5_A';
VRS_rd.Properties.VariableNames{6}='Ba6_A';
VRS_rd.Properties.VariableNames{7}='Ba7_A';


VRS_rd=retime(VRS_rd,'daily',@nanmedian);
%%
datevec(VRS_rd.Time(1)) % 2017 Aug --> begin in 2018 %[output:800b265e]
datevec(VRS_rd.Time(end)) %2025 %[output:78c06aca]

plotFigControl(VRS_rd,VRS_st.name); %[output:0bc4ee9d] %[output:2f3fa374] %[output:546a35d8] %[output:1ec484a2] %[output:32125439] %[output:5451cd93] %[output:31fcdde9] %[output:5b0205d3]
% 2 size cut, ok
% sc: ok, no negatives, no clear seasonal cycle

%%
% BP detection for abs
names_abs={'Ba1_A','Ba2_A','Ba3_A','Ba4_A','Ba5_A','Ba6_A','Ba7_A'}%{'BaB0_Ah','BaG0_Ah','BaR0_Ah'}; %[output:237a025f]
break_VRS_abs_BP=change_point_analysis_Def(VRS_rd,names_abs,0.05,'VRS','Absorption'); %[output:007f4f04] %[output:2a742efc] %[output:67b74ed8] %[output:924a9f47] %[output:25a29f50] %[output:0c32e95b]
T_VRS_abs_BP=make_table_breakpoints_def(break_VRS_abs_BP);


%%
lambdaAE7=[370 470 520 590 660 880 950];

VRS_cal=compute_exp_D(VRS_rd,names_abs,lambdaAE7); %[output:057dd989] %[output:646e44b9] %[output:55e4d87c] %[output:64044caa] %[output:23e17cb1] %[output:2ccb3e43] %[output:03a27ca5] %[output:4e593df6] %[output:40e4bfe1] %[output:00b887f0] %[output:00a1df7c] %[output:040d2bbc] %[output:315fe0c1] %[output:9617e5fb] %[output:6ea5c59d] %[output:6ed3feb0] %[output:943f4247] %[output:71e2e625] %[output:4bfcfd7e] %[output:24f54fc8] %[output:564054d1] %[output:673ee850] %[output:05e2133b] %[output:9750bcec] %[output:0e7f584c] %[output:431a7655] %[output:4e06df93] %[output:5075e2d8] %[output:7016a14b] %[output:62f0aad4] %[output:954e749b] %[output:6d244cb2] %[output:7f42381a] %[output:099a624e] %[output:9bec2a39]
plotFigControl_cal(VRS_cal,VRS_st.name); %[output:0c9dde2c] %[output:00c5d74f] %[output:3ba12721]
%%
% BP detection 

names_exps={'expA_bgAE', 'expA_brAE', 'expA_grAE','expA_fit'};
break_VRS_exps_BP=change_point_analysis_Def(VRS_cal,names_exps,0.05,'VRS','absorption exp'); %[output:337e7a4f] %[output:796a212d] %[output:73ac3817] %[output:9f5aff34]
T_VRS_exps_BP=make_table_breakpoints_def(break_VRS_exps_BP);

%%
%Questions:
%problems:
%%

VRS_tr=outerjoin(VRS_rd,VRS_cal);
VRS_tr.y=year(VRS_tr.Time);
% begin at the beginning of a year:2014
%end: 2026
P=timerange('1918-01-01','2026-01-01');
VRS_tr=VRS_tr(P,:);

VRS_tr.Ba1_A=[];
VRS_tr.Ba2_A=[];
VRS_tr.Ba4_A=[];
VRS_tr.Ba5_A=[];
VRS_tr.Ba6_A=[];
VRS_tr.Ba7_A=[];


VRS_tr.expA_bgAE=[];
VRS_tr.expA_brAE=[];
VRS_tr.expA_grAE=[];

VRS_tr.flag=[];
%%

%%
[VRS_result_MK,VRS_result_LMSlog,VRS_result_LMSlin]=all_trend_STN(VRS_tr,VRS_st); %[output:8f4b8502] %[output:97964538] %[output:3fbb52ba] %[output:46af2cbe] %[output:7f520dbb] %[output:2b14c5dd] %[output:1b899e50] %[output:74cd15c7]

writetable(VRS_result_MK,'VRS_res_MK.txt'); %, 'delimiter',',' )
writetable(VRS_result_LMSlog,'VRS_res_LMSlog.txt'); 
writetable(VRS_result_LMSlin,'VRS_res_LMSlin.txt'); 
plot_10y_in_two(VRS_result_MK, VRS_st,'y'); %[output:7a2cded8] %[output:6c626b14]
